const item = $input.first().json;
const data = item.body?.data || item.data || item;

const GROUP_JID = 'COLOQUE_O_JID_DO_SEU_GRUPO_AQUI@g.us';

// A instância é o número do próprio SEU NOME AQUI, que participa do grupo. As
// mensagens dele contam para os tópicos e para o Top, como as de qualquer um.
const NOME_PROPRIO = 'SEU NOME AQUI';

// O que o bot publica sai pelo mesmo número. Sem descartar, o resumo de ontem
// vira assunto do resumo de hoje. O bot nunca manda áudio, só esse texto.
const PREFIXOS_DO_BOT = ['📋 Resumo do dia', '📅 Resumo da semana'];

const remoteJid = data.key?.remoteJid;
const fromMe = data.key?.fromMe;

if (remoteJid !== GROUP_JID) {
  return [];
}

const remetenteJid = data.key?.participant || data.key?.remoteJid || '';
// Sempre o mesmo nome para as próprias mensagens: pushName não vem de forma
// confiável em fromMe, e dois nomes diferentes rachariam a contagem do Top.
const remetenteNome = fromMe === true ? NOME_PROPRIO : (data.pushName || remetenteJid);

const rawTs = data.messageTimestamp;
const ts = typeof rawTs === 'string' ? parseInt(rawTs, 10) : rawTs;
const data_ = Number.isFinite(ts) ? new Date(ts * 1000) : new Date();
const timestampIso = Number.isNaN(data_.getTime())
  ? new Date().toISOString()
  : data_.toISOString();

const texto = data.message?.conversation
  || data.message?.extendedTextMessage?.text
  || '';

if (texto) {
  // Compara sem os asteriscos de negrito, que mudam com o formato da mensagem.
  const semMarcacao = texto.replace(/\*/g, '').trimStart();
  if (fromMe === true && PREFIXOS_DO_BOT.some(prefixo => semMarcacao.startsWith(prefixo))) {
    return [];
  }

  const urlRegex = /(https?:\/\/[^\s]+)/g;
  const links = (texto.match(urlRegex) || []).join(', ');

  return [{
    json: {
      tipo: 'texto',
      remetente_nome: remetenteNome,
      remetente_jid: remetenteJid,
      texto,
      links,
      timestamp: timestampIso,
    },
  }];
}

// Sem texto: só segue adiante se for áudio, pro ramo de transcrição buscar a
// mídia e preencher o texto depois. Qualquer outra mídia (imagem, figurinha,
// vídeo, documento) continua fora de escopo e é descartada aqui.
const mensagemId = data.message?.audioMessage ? data.key?.id : null;
if (!mensagemId) {
  return [];
}

// A Evolution pode entregar mensagens com horas de atraso (nov/2026, dois dias
// de acúmulo). Áudio atrasado entra no resumo, mas não ganha resposta no grupo.
const RESPONDER_ATE_MS = 15 * 60 * 1000;
const recente = Number.isFinite(ts) && Date.now() - ts * 1000 <= RESPONDER_ATE_MS;

return [{
  json: {
    tipo: 'audio',
    remetente_nome: remetenteNome,
    remetente_jid: remetenteJid,
    timestamp: timestampIso,
    mensagem_id: mensagemId,
    recente,
  },
}];

const resposta = $input.first().json;
const base64 = resposta.base64;
const mimetype = resposta.mimetype || 'audio/ogg; codecs=opus';

// Sem base64, a mídia não veio (mensagem expirada, id errado, etc.). Deixa
// a execução falhar aqui — mesmo efeito de descartar a mensagem, sem poluir
// o resumo com um texto de erro.
if (!base64) {
  const id = $('Filtrar e extrair').first().json.mensagem_id || '?';
  throw new Error('Evolution API não devolveu base64 para a mensagem ' + id);
}

const buffer = Buffer.from(base64, 'base64');
const extensao = mimetype.includes('ogg') ? 'ogg' : 'bin';
const binaryData = await this.helpers.prepareBinaryData(buffer, `audio.${extensao}`, mimetype);

return [{
  json: {},
  binary: { data: binaryData },
}];

// remetente/timestamp vêm do node original: os nodes intermediários
// (Evolution API, Groq) substituem $json pelas próprias respostas.
const original = $('Filtrar e extrair').first().json;
const resposta = $input.first().json;
const transcricao = (resposta.text || '').trim();

if (!transcricao) {
  throw new Error('Groq não devolveu texto para a mensagem ' + (original.mensagem_id || '?'));
}

return [{
  json: {
    tipo: 'texto',
    remetente_nome: original.remetente_nome,
    remetente_jid: original.remetente_jid,
    texto: '[áudio transcrito] ' + transcricao,
    links: '',
    timestamp: original.timestamp,
  },
}];
